SET SESSION time_zone = '+00:00';
SET SESSION TRANSACTION READ ONLY;
START TRANSACTION WITH CONSISTENT SNAPSHOT, READ ONLY;
SELECT JSON_OBJECT('kind','database_info','queried_utc',UTC_TIMESTAMP(3),'mysql_version',VERSION(),'session_time_zone',@@session.time_zone);
SELECT JSON_OBJECT('kind','inspection','inspection_id',inspection_id,'created_at',created_at,'completed_at',completed_at,'updated_at',updated_at,'inference_time_ms',inference_time_ms,'inspection_status',inspection_status,'control_status',control_status,'persistence_status',persistence_status,'error_code',error_code,'model_version',model_version) FROM inspections WHERE inspection_id IN ('80b3c9ab-8b4c-4eb8-90b1-344ad22039c4','00bf0b8a-3220-4f16-ada7-e94dd401b3ce','5c24ef65-afbb-4917-8928-72fc1b0316de','a5012a91-b947-44da-bdd6-5bedd3c150ce','661b239d-57d3-4616-bf85-7f7c85e1275b','63cb91f7-70f7-4261-8933-62d80fe6fe76','c18c2ed9-1ff8-4dde-8c10-c1e5e5aff411','6cb7a7d8-be6d-4d72-a494-adf58134ea3d','7f1b4dfc-6b82-4532-aef3-ac079fc827f1') ORDER BY completed_at,inspection_id;
SELECT JSON_OBJECT('kind','control_attempt','id',id,'command_id',command_id,'inspection_id',inspection_id,'attempt_no',attempt_no,'requested_bin_code',requested_bin_code,'command_type',command_type,'control_status',control_status,'requested_at',requested_at,'responded_at',responded_at,'response_time_ms',response_time_ms,'failure_reason',failure_reason) FROM control_attempts WHERE inspection_id IN ('80b3c9ab-8b4c-4eb8-90b1-344ad22039c4','00bf0b8a-3220-4f16-ada7-e94dd401b3ce','5c24ef65-afbb-4917-8928-72fc1b0316de','a5012a91-b947-44da-bdd6-5bedd3c150ce','661b239d-57d3-4616-bf85-7f7c85e1275b','63cb91f7-70f7-4261-8933-62d80fe6fe76','c18c2ed9-1ff8-4dde-8c10-c1e5e5aff411','6cb7a7d8-be6d-4d72-a494-adf58134ea3d','7f1b4dfc-6b82-4532-aef3-ac079fc827f1') ORDER BY requested_at,inspection_id,attempt_no;
ROLLBACK;
